import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S08/S08E17.html","title":"S08E17 The One with the Tea Leaves","lang":"zh-CN","frontmatter":{"title":"S08E17 The One with the Tea Leaves","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":187},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":31.29,"words":9386},"filePathRelative":"语言/英语/Friends老友记/S08/S08E17.md"}`),l={name:`S08E17.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=a(`h1`,{id:`the-one-with-the-tea-leaves`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#the-one-with-the-tea-leaves`},[a(`span`,null,`The One with the Tea Leaves`)])],-1),c[1]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`有茶叶的那个`)])],-1),c[2]||=a(`p`,null,`The One With The Tea Leaves`,-1),c[3]||=a(`blockquote`,null,[a(`p`,null,`有茶叶的那个`)],-1),r(p,{src:`/audio/friends/S08/S08E17/001.mp3`}),c[4]||=i(),c[5]||=a(`strong`,null,`Teleplay by:`,-1),c[6]||=i(` Steven Rosenhaus`,-1),c[7]||=a(`blockquote`,null,[a(`p`,null,`史蒂文·罗森豪斯`)],-1),r(p,{src:`/audio/friends/S08/S08E17/002.mp3`}),c[8]||=t(` <strong>Story by:</strong> R. Lee Flemming, Jr.<blockquote><p>小R·李·弗莱明。</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>The Hallway, Rachel walks up the stairs and knocks on Joey’s door.</em></p><blockquote><p>🎬 <em>走廊上，瑞秋走上楼梯，敲乔伊的门。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E17/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Rachel Green:`,-1),c[11]||=i(` Joey? Are you in there?`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`乔伊？你在里面吗？`)],-1),c[13]||=a(`p`,null,`[Cut to inside Monica and Chandler’s, Monica, Chandler and Joey are eating breakfast.]`,-1),c[14]||=a(`blockquote`,null,[a(`p`,null,`[切到莫妮卡和钱德勒家，莫妮卡、钱德勒和乔伊正在吃早餐。]`)],-1),r(p,{src:`/audio/friends/S08/S08E17/004.mp3`}),c[15]||=i(),c[16]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[17]||=i(` (hearing Rachel and jumping up with his plate) Oh God! That’s Rachel!`,-1),c[18]||=a(`blockquote`,null,[a(`p`,null,`（听到瑞秋拿着盘子跳了起来）天哪！那是瑞秋！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/005.mp3`}),c[19]||=i(),c[20]||=a(`strong`,null,`Monica Geller:`,-1),c[21]||=i(` Joey, you have to talk to her!`,-1),c[22]||=a(`blockquote`,null,[a(`p`,null,`乔伊，你得跟她谈谈！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/006.mp3`}),c[23]||=i(),c[24]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[25]||=i(` No-no, I can’t! I can’t! Not after the other night, it’s just it’s…too weird, okay? Don’t tell her I’m here! (Turns to run to the bathroom and his bagel falls off the plate onto the floor.) Don’t eat that! (Runs to the bathroom as Rachel enters.)`,-1),c[26]||=a(`blockquote`,null,[a(`p`,null,`不，不，我不能！我不能！前几天晚上没有，只是…太奇怪了，好吗？别告诉她我在这儿！（转身跑到浴室，他的百吉饼从盘子上掉到了地板上。）别吃那个！（瑞秋进来时跑向浴室。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/007.mp3`}),c[27]||=i(),c[28]||=a(`strong`,null,`Rachel Green:`,-1),c[29]||=i(` Hey!`,-1),c[30]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/008.mp3`}),c[31]||=i(),c[32]||=a(`strong`,null,`Chandler Bing:`,-1),c[33]||=i(` Hey!`,-1),c[34]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/009.mp3`}),c[35]||=i(),c[36]||=a(`strong`,null,`Monica Geller:`,-1),c[37]||=i(` Hey Rachel!`,-1),c[38]||=a(`blockquote`,null,[a(`p`,null,`嘿，瑞秋！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/010.mp3`}),c[39]||=i(),c[40]||=a(`strong`,null,`Rachel Green:`,-1),c[41]||=i(` Is Joey here?`,-1),c[42]||=a(`blockquote`,null,[a(`p`,null,`乔伊在吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/011.mp3`}),c[43]||=i(),c[44]||=a(`strong`,null,`Chandler Bing:`,-1),c[45]||=i(` I don’t see him. (To Monica) Do you see him?`,-1),c[46]||=a(`blockquote`,null,[a(`p`,null,`我没看见他。（对莫妮卡）你看见他了吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/012.mp3`}),c[47]||=i(),c[48]||=a(`strong`,null,`Monica Geller:`,-1),c[49]||=i(` I don’t see him. Hey! Maybe he’s in the sugar bowl! (Opens the sugar bowl) Joey? Nope! (Closes the sugar bowl and they both laugh.)`,-1),c[50]||=a(`blockquote`,null,[a(`p`,null,`我没看见他。嘿也许他在糖碗里！（打开糖碗）乔伊？不！（合上糖碗，他们都笑了。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/013.mp3`}),c[51]||=i(),c[52]||=a(`strong`,null,`Rachel Green:`,-1),c[53]||=i(` Well, at least you make each other laugh.`,-1),c[54]||=a(`blockquote`,null,[a(`p`,null,`嗯，至少你们能让彼此开怀大笑。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/014.mp3`}),c[55]||=i(),c[56]||=a(`strong`,null,`Monica Geller:`,-1),c[57]||=i(` What’s up?`,-1),c[58]||=a(`blockquote`,null,[a(`p`,null,`怎么了？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/015.mp3`}),c[59]||=i(),c[60]||=a(`strong`,null,`Rachel Green:`,-1),c[61]||=i(` Well, I haven’t seen him since that night that he told me how he y’know… I don’t know, I think he’s avoiding me. Why is that bagel on the floor?`,-1),c[62]||=a(`blockquote`,null,[a(`p`,null,`嗯，自从那天晚上他告诉我他怎么知道后，我就再也没见过他了……我不知道，我想他是在逃避我。为什么面包圈在地板上？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/016.mp3`}),c[63]||=i(),c[64]||=a(`strong`,null,`Monica Geller:`,-1),c[65]||=i(` We were playing a game.`,-1),c[66]||=a(`blockquote`,null,[a(`p`,null,`我们在玩游戏。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/017.mp3`}),c[67]||=i(),c[68]||=a(`strong`,null,`Rachel Green:`,-1),c[69]||=i(` Ew, was Chandler naked? Sort of like a, like a ring toss kind of situation?`,-1),c[70]||=a(`blockquote`,null,[a(`p`,null,`呃，钱德勒是裸体的吗？有点像丢戒指之类的情况？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/018.mp3`}),c[71]||=i(),c[72]||=a(`strong`,null,`Monica Geller:`,-1),c[73]||=i(` Sure.`,-1),c[74]||=a(`blockquote`,null,[a(`p`,null,`当然。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/019.mp3`}),c[75]||=i(),c[76]||=a(`strong`,null,`Chandler Bing:`,-1),c[77]||=i(` What?! No! No!`,-1),c[78]||=a(`blockquote`,null,[a(`p`,null,`什么？！不不`)],-1),r(p,{src:`/audio/friends/S08/S08E17/020.mp3`}),c[79]||=i(),c[80]||=a(`strong`,null,`Rachel Green:`,-1),c[81]||=i(` All right. Well listen, if you see Joey will you just tell him uh…tell him I miss him. (Exits and Joey enters.)`,-1),c[82]||=a(`blockquote`,null,[a(`p`,null,`好的。听着，如果你看到乔伊，你就告诉他，嗯……告诉他我想他。（离开，乔伊进来。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/021.mp3`}),c[83]||=i(),c[84]||=a(`strong`,null,`Monica Geller:`,-1),c[85]||=i(` (To Joey) Okay, did you hear that?`,-1),c[86]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊）好的，你听到了吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/022.mp3`}),c[87]||=i(),c[88]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[89]||=i(` Yeah, a naked bagel game? (Picks up his dropped bagel.) (To Chandler) Dude, I don’t know. That’s a pretty small hole.`,-1),c[90]||=a(`blockquote`,null,[a(`p`,null,`是的，一个裸体的百吉饼游戏？（捡起掉在地上的百吉饼。）（对钱德勒）老兄，我不知道。那是一个相当小的洞。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/023.mp3`}),c[91]||=i(),c[92]||=a(`strong`,null,`Monica Geller:`,-1),c[93]||=i(` Honey, you gotta talk to her.`,-1),c[94]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，你得跟她谈谈。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/024.mp3`}),c[95]||=i(),c[96]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[97]||=i(` I can’t! Y’know? You guys don’t know what it’s like to put yourself out there like that and just get shot down.`,-1),c[98]||=a(`blockquote`,null,[a(`p`,null,`我不能！你知道吗？你们不知道这样把自己放在那里然后被枪杀是什么感觉。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/025.mp3`}),c[99]||=i(),c[100]||=a(`strong`,null,`Chandler Bing:`,-1),c[101]||=i(` (incredulous) I don’t know what that’s like?! Up until I was 25 I thought the only response to, "I love you," was, "Oh crap!"`,-1),c[102]||=a(`blockquote`,null,[a(`p`,null,`（怀疑）我不知道那是什么感觉？！直到我25岁，我还以为对“我爱你”的唯一回应是“哦，糟了！”`)],-1),r(p,{src:`/audio/friends/S08/S08E17/026.mp3`}),c[103]||=i(),c[104]||=a(`strong`,null,`Monica Geller:`,-1),c[105]||=i(` Hello? No rejection? I got shot down at fat camp! Boy, kids are mean when they’re hungry.`,-1),c[106]||=a(`blockquote`,null,[a(`p`,null,`喂？没有拒绝？我在脂肪营被枪杀了！孩子们饿的时候很刻薄。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/027.mp3`}),c[107]||=i(),c[108]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[109]||=i(` All right so, so what do I do?`,-1),c[110]||=a(`blockquote`,null,[a(`p`,null,`好吧，那我该怎么办？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/028.mp3`}),c[111]||=i(),c[112]||=a(`strong`,null,`Monica Geller:`,-1),c[113]||=i(` This is Rachel. I mean, what are you gonna do, never going to talk to her again? I mean I know it’s weird, it’s awkward, but you gotta at least try.`,-1),c[114]||=a(`blockquote`,null,[a(`p`,null,`我是瑞秋。我是说，你打算怎么做，再也不跟她说话了？我是说，我知道这很奇怪，很尴尬，但你至少得试试。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/029.mp3`}),c[115]||=i(),c[116]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[117]||=i(` Yeah. Okay. (Goes to take a bite out of the previously mentioned bagel.) Whoa! (Stops.) I almost forgot this was on your…`,-1),c[118]||=a(`blockquote`,null,[a(`p`,null,`是的。可以（去咬一口前面提到的百吉饼）哇！（停下来）我差点忘了这是你的…`)],-1),r(p,{src:`/audio/friends/S08/S08E17/030.mp3`}),c[119]||=t(` <strong>Chandler Bing:</strong> (interrupting him) We didn’t play it!!<blockquote><p>（打断他）我们没有玩！！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Central Perk, Phoebe is holding a book as she, Rachel, and Monica drink some tea as Chandler looks on.</em></p><blockquote><p>🎬 <em>中央公园，菲比拿着一本书，她、瑞秋和莫妮卡在钱德勒的注视下喝茶。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E17/031.mp3`}),c[120]||=i(),c[121]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[122]||=i(` Okay, so when you’re done with your tea I’ll look at your leaves and tell you your fortune.`,-1),c[123]||=a(`blockquote`,null,[a(`p`,null,`好吧，等你喝完茶，我会看看你的叶子，告诉你你的命运。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/032.mp3`}),c[124]||=i(),c[125]||=a(`strong`,null,`Chandler Bing:`,-1),c[126]||=i(` I didn’t know you read tea leaves.`,-1),c[127]||=a(`blockquote`,null,[a(`p`,null,`我不知道你在看茶叶。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/033.mp3`}),c[128]||=i(),c[129]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[130]||=i(` Oh yeah, I’ve done it for years. I actually stopped because I was so accurate. Y’know, and-and y’know, one of the great joys of life is it’s-it’s wondrous unpredictability. Y’know? And also tea tends to give me the trots.`,-1),c[131]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，我已经做了很多年了。实际上我停下来是因为我太准确了。你知道，而且你知道，生活中最大的乐趣之一就是它——它是不可思议的不可预测性。你知道吗？而且茶也能让我快跑。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/034.mp3`}),c[132]||=i(),c[133]||=a(`strong`,null,`Monica Geller:`,-1),c[134]||=i(` Okay, I’m done. Read mine.`,-1),c[135]||=a(`blockquote`,null,[a(`p`,null,`好了，我做完了。读我的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/035.mp3`}),c[136]||=i(),c[137]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[138]||=i(` Okay. (Looks at the leaves.) Ooh, I see a ladder. (Checks the book) Which can mean either a promotion or a violent death.`,-1),c[139]||=a(`blockquote`,null,[a(`p`,null,`好的。（看着树叶）哦，我看到一个梯子。（查阅书籍）这可能意味着升职或暴力死亡。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/036.mp3`}),c[140]||=i(),c[141]||=a(`strong`,null,`Monica Geller:`,-1),c[142]||=i(` (stunned) I-I’m the head chef. I-I can’t get promoted.`,-1),c[143]||=a(`blockquote`,null,[a(`p`,null,`（惊呆了）我是主厨。我不能升职。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/037.mp3`}),c[144]||=i(),c[145]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[146]||=i(` Uh-hmm. Uh-hmm, who’s next?`,-1),c[147]||=a(`blockquote`,null,[a(`p`,null,`嗯。嗯，下一个是谁？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/038.mp3`}),c[148]||=i(),c[149]||=a(`strong`,null,`Rachel Green:`,-1),c[150]||=i(` Okay, I’m done. Do mine.`,-1),c[151]||=a(`blockquote`,null,[a(`p`,null,`好了，我做完了。做我的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/039.mp3`}),c[152]||=i(),c[153]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[154]||=i(` Okay. (Reads the leaves) Umm, oh! Okay, I see a circle.`,-1),c[155]||=a(`blockquote`,null,[a(`p`,null,`好的。（读树叶）嗯，哦！好的，我看到一个圆圈。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/040.mp3`}),c[156]||=i(),c[157]||=a(`strong`,null,`Rachel Green:`,-1),c[158]||=i(` Ah.`,-1),c[159]||=a(`blockquote`,null,[a(`p`,null,`啊。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/041.mp3`}),c[160]||=i(),c[161]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[162]||=i(` Oh! (Checking the book) Which can either mean you’re having a baby or you’re gonna make a scientific discovery!`,-1),c[163]||=a(`blockquote`,null,[a(`p`,null,`哦！（查看书本）这可能意味着你要生孩子了，也可能意味着你要做出一项科学发现！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/042.mp3`}),c[164]||=i(),c[165]||=a(`strong`,null,`Rachel Green:`,-1),c[166]||=i(` Well, I have been spending a lot of time in the lab.`,-1),c[167]||=a(`blockquote`,null,[a(`p`,null,`嗯，我在实验室里呆了很多时间。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/043.mp3`}),c[168]||=i(),c[169]||=a(`strong`,null,`Chandler Bing:`,-1),c[170]||=i(` What does yours say Pheebs?`,-1),c[171]||=a(`blockquote`,null,[a(`p`,null,`你说菲比是什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/044.mp3`}),c[172]||=i(),c[173]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[174]||=i(` Umm… Wow, all right. (Checks the book.) Wow! Yay! Ooh, I’m gonna meet a guy! And really soon! And he’s gonna be the man of my dreams. Probably not the guy I had a dream about last night. (Points at Chandler.)`,-1),c[175]||=a(`blockquote`,null,[a(`p`,null,`嗯…哇，好吧。（查看书本）哇！耶！哦，我要去见一个人！真的很快！他将成为我的梦中情人。可能不是我昨晚梦见的那个人。（指着钱德勒。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/045.mp3`}),c[176]||=i(),c[177]||=a(`strong`,null,`Ross Geller:`,-1),c[178]||=i(` (entering) Hey! Has anyone seen my shirt? It’s a button down, like a, like a faded salmon?`,-1),c[179]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！有人看见我的衬衫了吗？这是一个按钮下来，像一个，像一个褪色的鲑鱼？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/046.mp3`}),c[180]||=i(),c[181]||=a(`strong`,null,`Monica Geller:`,-1),c[182]||=i(` You mean your pink shirt?`,-1),c[183]||=a(`blockquote`,null,[a(`p`,null,`你是说你的粉红色衬衫？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/047.mp3`}),c[184]||=i(),c[185]||=a(`strong`,null,`Ross Geller:`,-1),c[186]||=i(` Faded salmon color.`,-1),c[187]||=a(`blockquote`,null,[a(`p`,null,`褪色的鲑鱼色。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/048.mp3`}),c[188]||=i(),c[189]||=a(`strong`,null,`Monica Geller:`,-1),c[190]||=i(` No, I-I haven’t seen your pink shirt.`,-1),c[191]||=a(`blockquote`,null,[a(`p`,null,`没有，我没有看到你的粉红色衬衫。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/049.mp3`}),c[192]||=i(),c[193]||=a(`strong`,null,`Ross Geller:`,-1),c[194]||=i(` Great! Great. Then I must’ve left it at Mona’s. I knew it!`,-1),c[195]||=a(`blockquote`,null,[a(`p`,null,`太好了！伟大的那我一定是把它忘在Mona家了。我就知道！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/050.mp3`}),c[196]||=i(),c[197]||=a(`strong`,null,`Chandler Bing:`,-1),c[198]||=i(` Well, I’m sure you get another one at Ann Taylor’s.`,-1),c[199]||=a(`blockquote`,null,[a(`p`,null,`嗯，我敢肯定你在安·泰勒家又买了一个。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/051.mp3`}),c[200]||=i(),c[201]||=a(`strong`,null,`Ross Geller:`,-1),c[202]||=i(` That’s my favorite shirt! Okay? I love that shirt!`,-1),c[203]||=a(`blockquote`,null,[a(`p`,null,`那是我最喜欢的衬衫！可以我喜欢那件衬衫！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/052.mp3`}),c[204]||=i(),c[205]||=a(`strong`,null,`Rachel Green:`,-1),c[206]||=i(` Well just ask Mona to give it back!`,-1),c[207]||=a(`blockquote`,null,[a(`p`,null,`那就让蒙娜把它还给我吧！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/053.mp3`}),c[208]||=i(),c[209]||=a(`strong`,null,`Ross Geller:`,-1),c[210]||=i(` I don’t know. I mean I-I guess I could. It’s just that we didn’t really end things such good terms. And if I go over there I’d be ignoring the one thing she asked me to do when we broke up, jump up my own ass and die. (Walks away.)`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`我不知道。我是说，我想我可以。只是我们并没有以这么好的方式结束这一切。如果我去那里，我会忽略我们分手时她让我做的一件事，跳起来去死。（走开了。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/054.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[214]||=i(` (noticing a guy sitting by the green post looking at her) Oh wait a second you guys…for the last couple weeks I’ve been that guy everywhere I go. We take the same bus. We go to the same bookstore, the same dry cleaners; maybe he’s the tea guy. (He gets up to leave, and smiles at Phoebe.)`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`（注意到一个男人坐在绿色柱子旁看着她）哦，等一下，你们这些家伙……过去几周，无论我走到哪里，我都是那个家伙。我们坐同一辆公共汽车。我们去同一家书店，同一家干洗店；也许他就是那个卖茶的。（他起身离开，对菲比微笑。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/055.mp3`}),c[216]||=i(),c[217]||=a(`strong`,null,`Chandler Bing:`,-1),c[218]||=i(` Phoebe, did you see that?! He totally checked you out! He is so cute! (Looking at his tea.) Mine has a picture of The Village People, what does that mean?`,-1),c[219]||=a(`blockquote`,null,[a(`p`,null,`菲比，你看到了吗？！他彻底检查了你！他真可爱！（看着他的茶）我的有一张村里人的照片，这是什么意思？`)],-1),c[220]||=a(`p`,null,[a(`em`,null,`(Joey enters.)`)],-1),c[221]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊进来了。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/056.mp3`}),c[222]||=i(),c[223]||=a(`strong`,null,`Rachel Green:`,-1),c[224]||=i(` Hi!`,-1),c[225]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/057.mp3`}),c[226]||=i(),c[227]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[228]||=i(` Hey.`,-1),c[229]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),c[230]||=a(`p`,null,[a(`em`,null,`(He slowly walks to the other side of the couch and sits down at the table, an awkward silence follows.)`)],-1),c[231]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他慢慢地走到沙发的另一边，在桌子旁坐下，接着是尴尬的沉默。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/058.mp3`}),c[232]||=i(),c[233]||=a(`strong`,null,`Rachel Green:`,-1),c[234]||=i(` Hi.`,-1),c[235]||=a(`blockquote`,null,[a(`p`,null,`嗨。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/059.mp3`}),c[236]||=i(),c[237]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[238]||=i(` Hi.`,-1),c[239]||=a(`blockquote`,null,[a(`p`,null,`嗨。`)],-1),c[240]||=a(`p`,null,[a(`em`,null,`(More awkward silence.)`)],-1),c[241]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（更尴尬的沉默。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/060.mp3`}),c[242]||=i(),c[243]||=a(`strong`,null,`Monica Geller:`,-1),c[244]||=i(` Tea gives Phoebe the trots.`,-1),c[245]||=a(`blockquote`,null,[a(`p`,null,`茶让菲比快跑。`)],-1),c[246]||=a(`hr`,null,null,-1),c[247]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Chandler's, Chandler is cooking as Rachel paces nervously.`)],-1),c[248]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和钱德勒家，钱德勒正在做饭，瑞秋紧张地踱步。`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/061.mp3`}),c[249]||=i(),c[250]||=a(`strong`,null,`Rachel Green:`,-1),c[251]||=i(` So I thought Joey and I would be okay once we hung out, but it’s not even like we know how to be with each other anymore.`,-1),c[252]||=a(`blockquote`,null,[a(`p`,null,`所以我以为乔伊和我出去玩后会没事的，但我们甚至都不知道如何相处了。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/062.mp3`}),c[253]||=i(),c[254]||=a(`strong`,null,`Chandler Bing:`,-1),c[255]||=i(` I know it’s tough now, but things will get better.`,-1),c[256]||=a(`blockquote`,null,[a(`p`,null,`我知道现在很艰难，但事情会好转的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/063.mp3`}),c[257]||=i(),c[258]||=a(`strong`,null,`Rachel Green:`,-1),c[259]||=i(` How do you know that? What if it just gets worse and worse and worse, to the point where we can’t even be in the same room with each other?!`,-1),c[260]||=a(`blockquote`,null,[a(`p`,null,`你怎么知道的？如果情况变得越来越糟，我们甚至不能在同一个房间里吗？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/064.mp3`}),c[261]||=i(),c[262]||=a(`strong`,null,`Chandler Bing:`,-1),c[263]||=i(` I’m not great at the advice, can I interest you in a sarcastic comment? Some cheese?`,-1),c[264]||=a(`blockquote`,null,[a(`p`,null,`我对这个建议不在行，我能给你一个讽刺的评论吗？一些奶酪？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/065.mp3`}),c[265]||=i(),c[266]||=a(`strong`,null,`Monica Geller:`,-1),c[267]||=i(` Honey, what is the Bruce Springsteen CD in the Kat Stevens case?`,-1),c[268]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，凯特·史蒂文斯案件中布鲁斯·斯普林斯汀的CD是什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/066.mp3`}),c[269]||=i(),c[270]||=a(`strong`,null,`Chandler Bing:`,-1),c[271]||=i(` Let’s just say if I can’t find the right CD case I just put it in the nearest one.`,-1),c[272]||=a(`blockquote`,null,[a(`p`,null,`如果我找不到合适的CD盒，我就把它放在最近的一个。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/067.mp3`}),c[273]||=i(),c[274]||=a(`strong`,null,`Monica Geller:`,-1),c[275]||=i(` Okay, where is the Kat Stevens CD?`,-1),c[276]||=a(`blockquote`,null,[a(`p`,null,`好的，凯特·史蒂文斯的CD在哪里？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/068.mp3`}),c[277]||=i(),c[278]||=a(`strong`,null,`Chandler Bing:`,-1),c[279]||=i(` In the James Taylor case.`,-1),c[280]||=a(`blockquote`,null,[a(`p`,null,`在詹姆斯·泰勒案中。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/069.mp3`}),c[281]||=i(),c[282]||=a(`strong`,null,`Monica Geller:`,-1),c[283]||=i(` Where is the James Taylor CD?`,-1),c[284]||=a(`blockquote`,null,[a(`p`,null,`詹姆斯·泰勒的CD在哪里？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/070.mp3`}),c[285]||=i(),c[286]||=a(`strong`,null,`Chandler Bing:`,-1),c[287]||=i(` Honey, I’m gonna save you some time, 200 CDs, not one of them in the right case.`,-1),c[288]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，我会给你省点时间，200张CD，不是一张放在合适的盒子里的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/071.mp3`}),c[289]||=i(),c[290]||=a(`strong`,null,`Monica Geller:`,-1),c[291]||=i(` Okay. No need to panic. Deep breathes everyone. Okay umm uh, we’re just gonna have to spend some time and put the CDs in the right cases.`,-1),c[292]||=a(`blockquote`,null,[a(`p`,null,`好的。不必惊慌。每个人都深呼吸。好吧，我们得花点时间把CD放在合适的盒子里。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/072.mp3`}),c[293]||=i(),c[294]||=a(`strong`,null,`Chandler Bing:`,-1),c[295]||=i(` Well, if we’re gonna do that we should come up with some kind of order. Y’know alphabetically or by genre?`,-1),c[296]||=a(`blockquote`,null,[a(`p`,null,`好吧，如果我们要这么做的话，我们应该制定一些命令。你知道按字母顺序还是按体裁？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/073.mp3`}),c[297]||=i(),c[298]||=a(`strong`,null,`Monica Geller:`,-1),c[299]||=i(` Hmm, I don’t know. We really have to talk this through.`,-1),c[300]||=a(`blockquote`,null,[a(`p`,null,`嗯，我不知道。我们真的得好好谈谈。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/074.mp3`}),c[301]||=i(),c[302]||=a(`strong`,null,`Rachel Green:`,-1),c[303]||=i(` Oh my God!! You guys have such problems!! I feel so terrible for you!`,-1),c[304]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天哪！！你们这些家伙有这样的问题！！我真替你难过！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/075.mp3`}),c[305]||=i(),c[306]||=a(`strong`,null,`Monica Geller:`,-1),c[307]||=i(` Okay, I-I’m sorry. You and Joey, your both focusing on this uncomfortable thing, what you need to do is to change the subject. Next time you see him try to get him talking about something else.`,-1),c[308]||=a(`blockquote`,null,[a(`p`,null,`好吧，对不起。你和乔伊，你都在关注这件不舒服的事情，你需要做的是改变话题。下次你看到他时，试着让他说点别的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/076.mp3`}),c[309]||=i(),c[310]||=a(`strong`,null,`Rachel Green:`,-1),c[311]||=i(` Oh yeah. That makes sense.`,-1),c[312]||=a(`blockquote`,null,[a(`p`,null,`哦，是的。这是有道理的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/077.mp3`}),c[313]||=i(),c[314]||=a(`strong`,null,`Monica Geller:`,-1),c[315]||=i(` Yeah, like I don’t know, maybe you have a work problem that you need his advice on.`,-1),c[316]||=a(`blockquote`,null,[a(`p`,null,`是啊，好像我不知道，也许你有工作上的问题需要他的建议。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/078.mp3`}),c[317]||=i(),c[318]||=a(`strong`,null,`Rachel Green:`,-1),c[319]||=i(` Ooh, I can do that.`,-1),c[320]||=a(`blockquote`,null,[a(`p`,null,`哦，我能做到。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/079.mp3`}),c[321]||=i(),c[322]||=a(`strong`,null,`Monica Geller:`,-1),c[323]||=i(` Good. (To Chandler) Uh honey, the Miami Vice soundtrack? Really?`,-1),c[324]||=a(`blockquote`,null,[a(`p`,null,`好的。（对钱德勒）亲爱的，迈阿密副警长的配乐？真正地`)],-1),r(p,{src:`/audio/friends/S08/S08E17/080.mp3`}),c[325]||=i(),c[326]||=a(`strong`,null,`Chandler Bing:`,-1),c[327]||=i(` They were just giving those away at the store (off Monica’s look) in exchange for money.`,-1),c[328]||=a(`blockquote`,null,[a(`p`,null,`他们只是在商店里把这些东西送人（用莫妮卡的表情）来换钱。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/081.mp3`}),c[329]||=i(),c[330]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[331]||=i(` (entering) Hey!`,-1),c[332]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/082.mp3`}),c[333]||=i(),c[334]||=a(`strong`,null,`Rachel Green:`,-1),c[335]||=i(` Hi.`,-1),c[336]||=a(`blockquote`,null,[a(`p`,null,`嗨。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/083.mp3`}),c[337]||=i(),c[338]||=a(`strong`,null,`Monica Geller:`,-1),c[339]||=i(` Uh I really don’t know what to tell you Rach, I really don’t. I mean, maybe Joey can help you out with your, with your big work problem.`,-1),c[340]||=a(`blockquote`,null,[a(`p`,null,`呃，我真的不知道该告诉你什么，瑞秋，我真的不知道。我是说，也许乔伊可以帮你解决你的工作难题。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/084.mp3`}),c[341]||=i(),c[342]||=a(`strong`,null,`Rachel Green:`,-1),c[343]||=i(` What?`,-1),c[344]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/085.mp3`}),c[345]||=i(),c[346]||=a(`strong`,null,`Monica Geller:`,-1),c[347]||=i(` Yeah Joey she’s…Rachel’s got this really big work problem, and it is a head scratcher. Wow! (To Chandler) Y’know what, if we’re gonna make dinner we’re gonna have to leave. Yeah. (She and Chandler exit.)`,-1),c[348]||=a(`blockquote`,null,[a(`p`,null,`是的，乔伊，她…瑞秋的工作有很大的问题，这是一个让人头疼的问题。哇！（对钱德勒）你知道吗，如果我们要做晚饭，我们就得走了。是 啊（她和钱德勒离开了。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/086.mp3`}),c[349]||=i(),c[350]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[351]||=i(` So you uh, have a…big work problem?`,-1),c[352]||=a(`blockquote`,null,[a(`p`,null,`所以你，呃，工作有大问题？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/087.mp3`}),c[353]||=i(),c[354]||=a(`strong`,null,`Rachel Green:`,-1),c[355]||=i(` Yeah it’s umm… Yeah it’s uh… It-it’s y’know—It’s nothing.`,-1),c[356]||=a(`blockquote`,null,[a(`p`,null,`是的，嗯……是的，嗯……你知道，这没什么。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/088.mp3`}),c[357]||=i(),c[358]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[359]||=i(` Huh. Okay. (Awkward silence.) So uh, I think I’m gonna take off.`,-1),c[360]||=a(`blockquote`,null,[a(`p`,null,`嗯。可以（尴尬的沉默）所以呃，我想我要走了。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/089.mp3`}),c[361]||=i(),c[362]||=a(`strong`,null,`Rachel Green:`,-1),c[363]||=i(` Yeah—No wait! Joey no wait it is. It’s something. It’s-it’s umm…it’s my boss.`,-1),c[364]||=a(`blockquote`,null,[a(`p`,null,`是的，不，等等！乔伊，不，等等。这很重要。是我的老板。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/090.mp3`}),c[365]||=i(),c[366]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[367]||=i(` Yeah?`,-1),c[368]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/091.mp3`}),c[369]||=i(),c[370]||=a(`strong`,null,`Rachel Green:`,-1),c[371]||=i(` Yeah, and umm my baby.`,-1),c[372]||=a(`blockquote`,null,[a(`p`,null,`是啊，嗯，我的宝贝。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/092.mp3`}),c[373]||=i(),c[374]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[375]||=i(` Yeah?`,-1),c[376]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/093.mp3`}),c[377]||=i(),c[378]||=a(`strong`,null,`Rachel Green:`,-1),c[379]||=i(` My boss wants to buy my baby!`,-1),c[380]||=a(`blockquote`,null,[a(`p`,null,`我老板想买我的孩子！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/094.mp3`}),c[381]||=i(),c[382]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[383]||=i(` What?! Oh my-oh my God!`,-1),c[384]||=a(`blockquote`,null,[a(`p`,null,`什么？！我的天啊！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/095.mp3`}),c[385]||=i(),c[386]||=a(`strong`,null,`Rachel Green:`,-1),c[387]||=i(` I know I told you, it’s a really big problem.`,-1),c[388]||=a(`blockquote`,null,[a(`p`,null,`我知道我告诉过你，这真是个大问题。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/096.mp3`}),c[389]||=i(),c[390]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[391]||=i(` What he wants to buy your baby?!`,-1),c[392]||=a(`blockquote`,null,[a(`p`,null,`他想给你的孩子买什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/097.mp3`}),c[393]||=i(),c[394]||=a(`strong`,null,`Rachel Green:`,-1),c[395]||=i(` Can you believe that?!`,-1),c[396]||=a(`blockquote`,null,[a(`p`,null,`你能相信吗？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/098.mp3`}),c[397]||=i(),c[398]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[399]||=i(` That’s crazy!`,-1),c[400]||=a(`blockquote`,null,[a(`p`,null,`那太疯狂了！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/099.mp3`}),c[401]||=i(),c[402]||=a(`strong`,null,`Rachel Green:`,-1),c[403]||=i(` That’s what I told him!`,-1),c[404]||=a(`blockquote`,null,[a(`p`,null,`我就是这么跟他说的！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/100.mp3`}),c[405]||=i(),c[406]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[407]||=i(` Okay, how did this even happen?`,-1),c[408]||=a(`blockquote`,null,[a(`p`,null,`好吧，这是怎么发生的？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/101.mp3`}),c[409]||=i(),c[410]||=a(`strong`,null,`Rachel Green:`,-1),c[411]||=i(` Well I’ll tell ya! (Pause) See uh my-my boss and his wife—They-they can’t have children. So umm, and that—we were at the Christmas party, and he got drunk, and he said to me, "Rachel, I want to buy your baby."`,-1),c[412]||=a(`blockquote`,null,[a(`p`,null,`我会告诉你的！（停顿）看看我的老板和他的妻子他们不能生孩子。我们在圣诞晚会上，他喝醉了，他对我说，“瑞秋，我想买你的孩子。”`)],-1),r(p,{src:`/audio/friends/S08/S08E17/102.mp3`}),c[413]||=i(),c[414]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[415]||=i(` Man! When you said it was a problem about your boss and the baby I figured it was something about maternity leave.`,-1),c[416]||=a(`blockquote`,null,[a(`p`,null,`老兄！当你说这是你老板和孩子的问题时，我想是产假的问题。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/103.mp3`}),c[417]||=i(),c[418]||=a(`strong`,null,`Rachel Green:`,-1),c[419]||=i(` Ohh! Yeah! (Pause) Yeah that-that would’ve been a much simpler problem.`,-1),c[420]||=a(`blockquote`,null,[a(`p`,null,`哦！是 啊（停顿）是的，那是一个简单得多的问题。`)],-1),c[421]||=a(`hr`,null,null,-1),c[422]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`A newsstand, Phoebe is looking at a magazine as the guy from before walks by and picks up a newspaper.`)],-1),c[423]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`在一个报摊上，菲比正在看一本杂志，之前的那个家伙走过来拿起一份报纸。`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/104.mp3`}),c[424]||=i(),c[425]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[426]||=i(` Oh hello.`,-1),c[427]||=a(`blockquote`,null,[a(`p`,null,`哦，你好。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/105.mp3`}),c[428]||=i(),c[429]||=a(`strong`,null,`Guy:`,-1),c[430]||=i(` Oh, it’s you. I see you everywhere. I’m Jim, Jim Nelson.`,-1),c[431]||=a(`blockquote`,null,[a(`p`,null,`哦，是你。我到处都能看到你。我是吉姆，吉姆·尼尔森。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/106.mp3`}),c[432]||=i(),c[433]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[434]||=i(` Oh Jim, Jim Nelson I’m Phoebe, Phoebe Buffay. We certainly have been seeing a lot of each other lately.`,-1),c[435]||=a(`blockquote`,null,[a(`p`,null,`哦，吉姆，吉姆·尼尔森，我是菲比，菲比·布菲。我们最近确实经常见面。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/107.mp3`}),c[436]||=i(),c[437]||=a(`strong`,null,`Jim:`,-1),c[438]||=i(` We have. Maybe we’ll be seeing each other at dinner tomorrow night, say around 8 o’clock?`,-1),c[439]||=a(`blockquote`,null,[a(`p`,null,`我们有。也许我们会在明晚的晚餐上见面，比如说8点左右？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/108.mp3`}),c[440]||=i(),c[441]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[442]||=i(` Well, maybe we will. (Starts to walk away.) Oh! (She turns around and the exchange information.)`,-1),c[443]||=a(`blockquote`,null,[a(`p`,null,`嗯，也许我们会的。（开始走开）哦！（她转过身来，交换信息。）`)],-1),c[444]||=a(`hr`,null,null,-1),c[445]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Outside Mona’s Apartment, Ross is knocking on the door.`)],-1),c[446]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`在莫娜的公寓外，罗斯正在敲门。`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/109.mp3`}),c[447]||=i(),c[448]||=a(`strong`,null,`Ross Geller:`,-1),c[449]||=i(` Mona? (There’s no answer, so he starts to leave but remembers where her extra key is. He reaches atop a hall light just outside her door and grabs the key. He looks at in triumph as the pain from it being hot moves along his nervous system to his brain, and when it arrives his brain orders his hand to drop the hot key and his mouth to squeal in pain. After dropping the key he pulls his shirtsleeve over his hand and uses the key to open the door and enter Mona’s apartment.) Okay, if I were a salmon shirt, where would I be? (He hears a key in the door and as it opens he dives behind the couch.)`,-1),c[450]||=a(`blockquote`,null,[a(`p`,null,`莫娜？（没有人回答，所以他开始离开，但他记得她多余的钥匙在哪里。他把手伸到她门外的门厅灯上，抓住钥匙。他得意地看着疼痛沿着他的神经系统传到他的大脑，当疼痛到来时，他的大脑命令他的手放下热钥匙，他的嘴痛苦地尖叫。Af他放下钥匙，把衬衫袖子拉到手上，用钥匙打开门，进入莫娜的公寓。）好吧，如果我是一件鲑鱼衬衫，我会在哪里？（他听到门里有钥匙的声音，当钥匙打开时，他潜到沙发后面。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/110.mp3`}),c[451]||=i(),c[452]||=a(`strong`,null,`Mona:`,-1),c[453]||=i(` (entering, with her date) I am so sorry I spilled wine all over your shirt.`,-1),c[454]||=a(`blockquote`,null,[a(`p`,null,`（带着她的约会对象进来）我很抱歉把酒洒到你的衬衫上了。`)],-1),c[455]||=a(`p`,null,`Mona's Date: Oh, it’s okay.`,-1),c[456]||=a(`blockquote`,null,[a(`p`,null,`哦，没关系。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/111.mp3`}),c[457]||=i(),c[458]||=a(`strong`,null,`Mona:`,-1),c[459]||=i(` No, it’s still wet. Y’know what? Let me get it out before it sets. Ooh, I have something you can wear. Here. (Hands him Ross’s shirt.)`,-1),c[460]||=a(`blockquote`,null,[a(`p`,null,`不，还是湿的。你知道吗？让我在它开始之前把它拿出来。哦，我有你可以穿的东西。在这里（递给他罗斯的衬衫。）`)],-1),c[461]||=a(`p`,null,`Mona's Date: Oh umm, I-I don’t know if I want to wear a woman’s shirt.`,-1),c[462]||=a(`blockquote`,null,[a(`p`,null,`哦，嗯，我不知道我想不想穿女人的衬衫。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/112.mp3`}),c[463]||=t(` <strong>Mona:</strong> No-no that’s a man’s shirt.<blockquote><p>不，不，那是男式衬衫。</p></blockquote><p>Mona&#39;s Date: It’s awfully pink. (Ross mouths, &quot;It’s salmon!&quot;)</p><blockquote><p>它是非常粉红色的。（罗斯说，“这是鲑鱼！”</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, Monica and Chandler are sorting their CDs.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒，莫妮卡和钱德勒正在整理他们的CD。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E17/113.mp3`}),c[464]||=i(),c[465]||=a(`strong`,null,`Chandler Bing:`,-1),c[466]||=i(` Oh my God, honey we are so meant to be together. We both have copies of the Annie soundtrack.`,-1),c[467]||=a(`blockquote`,null,[a(`p`,null,`我的天啊，亲爱的，我们注定要在一起。我们都有安妮的配乐。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/114.mp3`}),c[468]||=i(),c[469]||=a(`strong`,null,`Monica Geller:`,-1),c[470]||=i(` Honey, both yours.`,-1),c[471]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，都是你的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/115.mp3`}),c[472]||=i(),c[473]||=a(`strong`,null,`Rachel Green:`,-1),c[474]||=i(` (entering) Hey! Great advice on that Joey thing!`,-1),c[475]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！关于乔伊那件事的好建议！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/116.mp3`}),c[476]||=i(),c[477]||=a(`strong`,null,`Monica Geller:`,-1),c[478]||=i(` Yeah? The work problem?`,-1),c[479]||=a(`blockquote`,null,[a(`p`,null,`是吗？工作问题？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/117.mp3`}),c[480]||=i(),c[481]||=a(`strong`,null,`Rachel Green:`,-1),c[482]||=i(` Oh it was perfect! I mean it really felt like he was my friend again.`,-1),c[483]||=a(`blockquote`,null,[a(`p`,null,`哦，太完美了！我的意思是他真的觉得他又是我的朋友了。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/118.mp3`}),c[484]||=i(),c[485]||=a(`strong`,null,`Chandler Bing:`,-1),c[486]||=i(` What problem did you tell him you had?`,-1),c[487]||=a(`blockquote`,null,[a(`p`,null,`你告诉他你有什么问题？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/119.mp3`}),c[488]||=t(` <strong>Rachel Green:</strong> Oh that’s not important. The point is, I really—I think everything’s gonna be okay.<blockquote><p>哦，那不重要。关键是，我真的觉得一切都会好起来的。</p></blockquote><hr><p>🎬 <em>Mr. Zelner’s Office, he’s in a meeting as Joey bursts in.</em></p><blockquote><p>🎬 <em>泽纳先生的办公室，他正在开会，乔伊突然进来。</em></p></blockquote><p>Mr. Zelner: May I help you?</p><blockquote><p>我能为您效劳吗？</p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E17/120.mp3`}),c[489]||=t(` <strong>Joey Tribbiani:</strong> Do you think you can just buy my friends baby?!<blockquote><p>你觉得你可以买我朋友的孩子吗？！</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>A restaurant, Phoebe and Jim are on their date.</em></p><blockquote><p>🎬 <em>一家餐厅，菲比和吉姆正在约会。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E17/121.mp3`}),c[490]||=i(),c[491]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[492]||=i(` Isn’t it funny how we kept running into each other? It’s as if someone really wants us to be together.`,-1),c[493]||=a(`blockquote`,null,[a(`p`,null,`我们老是碰面，这不是很有趣吗？好像有人真的希望我们在一起。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/122.mp3`}),c[494]||=i(),c[495]||=a(`strong`,null,`Jim:`,-1),c[496]||=i(` Someone does. Me.`,-1),c[497]||=a(`blockquote`,null,[a(`p`,null,`有人喜欢。我`)],-1),r(p,{src:`/audio/friends/S08/S08E17/123.mp3`}),c[498]||=i(),c[499]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[500]||=i(` Oh, witty banter. Well done.`,-1),c[501]||=a(`blockquote`,null,[a(`p`,null,`哦，诙谐的玩笑。做得好。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/124.mp3`}),c[502]||=i(),c[503]||=a(`strong`,null,`Jim:`,-1),c[504]||=i(` So, tell me a little bit about yourself.`,-1),c[505]||=a(`blockquote`,null,[a(`p`,null,`那么，跟我说说你自己吧。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/125.mp3`}),c[506]||=i(),c[507]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[508]||=i(` Oh okay, well I’m a masseuse, and I used to work at this place…`,-1),c[509]||=a(`blockquote`,null,[a(`p`,null,`哦，好吧，我是一名按摩师，我以前在这个地方工作…`)],-1),r(p,{src:`/audio/friends/S08/S08E17/126.mp3`}),c[510]||=i(),c[511]||=a(`strong`,null,`Jim:`,-1),c[512]||=i(` Do you like to party?`,-1),c[513]||=a(`blockquote`,null,[a(`p`,null,`你喜欢聚会吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/127.mp3`}),c[514]||=i(),c[515]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[516]||=i(` I-I-I like, I like parties.`,-1),c[517]||=a(`blockquote`,null,[a(`p`,null,`我喜欢，我喜欢派对。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/128.mp3`}),c[518]||=i(),c[519]||=a(`strong`,null,`Jim:`,-1),c[520]||=i(` You’re wild, aren’t ya?`,-1),c[521]||=a(`blockquote`,null,[a(`p`,null,`你很野，是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/129.mp3`}),c[522]||=i(),c[523]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[524]||=i(` Yeah I guess, a little.`,-1),c[525]||=a(`blockquote`,null,[a(`p`,null,`是的，我想有一点。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/130.mp3`}),c[526]||=i(),c[527]||=a(`strong`,null,`Jim:`,-1),c[528]||=i(` It ain’t no thing, I’m wild too.`,-1),c[529]||=a(`blockquote`,null,[a(`p`,null,`没什么，我也很野。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/131.mp3`}),c[530]||=i(),c[531]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[532]||=i(` (a little freaked out) So! Umm, anyway I-I lived in New York, someone wildly I guess, for umm—Well since I was fourteen.`,-1),c[533]||=a(`blockquote`,null,[a(`p`,null,`（有点吓坏了）所以！嗯，不管怎么说，我住在纽约，我想是个疯狂的人，因为从我十四岁起。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/132.mp3`}),c[534]||=i(),c[535]||=a(`strong`,null,`Jim:`,-1),c[536]||=i(` I’m sorry. I’m staring. It’s just that you have the most beautiful eyes.`,-1),c[537]||=a(`blockquote`,null,[a(`p`,null,`对不起。我盯着看。只是你有一双最美丽的眼睛。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/133.mp3`}),c[538]||=i(),c[539]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[540]||=i(` Oh stop it.`,-1),c[541]||=a(`blockquote`,null,[a(`p`,null,`哦，别说了。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/134.mp3`}),c[542]||=i(),c[543]||=a(`strong`,null,`Jim:`,-1),c[544]||=i(` And your breasts! Hmm!!!`,-1),c[545]||=a(`blockquote`,null,[a(`p`,null,`还有你的胸部！隐马尔可夫模型！！！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/135.mp3`}),c[546]||=i(),c[547]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[548]||=i(` Okay. Umm look, you’re coming on a little strong. But I’m going to give you the benefit of the doubt, because it seems the universe really wants to be together. So, why don’t we just start over okay? And you can just tell me about yourself.`,-1),c[549]||=a(`blockquote`,null,[a(`p`,null,`好的。嗯，看，你变得有点坚强了。但我要给你们一个怀疑的好处，因为似乎宇宙真的想在一起。那么，我们为什么不重新开始呢？你可以告诉我你自己的情况。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/136.mp3`}),c[550]||=i(),c[551]||=a(`strong`,null,`Jim:`,-1),c[552]||=i(` All right.`,-1),c[553]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/137.mp3`}),c[554]||=i(),c[555]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[556]||=i(` Okay.`,-1),c[557]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/138.mp3`}),c[558]||=i(),c[559]||=a(`strong`,null,`Jim:`,-1),c[560]||=i(` I write erotic novels, for children.`,-1),c[561]||=a(`blockquote`,null,[a(`p`,null,`我为孩子们写情色小说。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/139.mp3`}),c[562]||=i(),c[563]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[564]||=i(` What?!`,-1),c[565]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/140.mp3`}),c[566]||=i(),c[567]||=a(`strong`,null,`Jim:`,-1),c[568]||=i(` They’re wildly unpopular.`,-1),c[569]||=a(`blockquote`,null,[a(`p`,null,`他们非常不受欢迎。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/141.mp3`}),c[570]||=i(),c[571]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[572]||=i(` Oh my God!`,-1),c[573]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/142.mp3`}),c[574]||=i(),c[575]||=a(`strong`,null,`Jim:`,-1),c[576]||=i(` Oh also, you might be interested to know that I have a Ph.D.`,-1),c[577]||=a(`blockquote`,null,[a(`p`,null,`哦，还有，你可能有兴趣知道我有博士学位。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/143.mp3`}),c[578]||=i(),c[579]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[580]||=i(` Wow! You do?`,-1),c[581]||=a(`blockquote`,null,[a(`p`,null,`哇！是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/144.mp3`}),c[582]||=i(),c[583]||=a(`strong`,null,`Jim:`,-1),c[584]||=i(` Yeah, (looks at his crotch) a Pretty Huge…`,-1),c[585]||=a(`blockquote`,null,[a(`p`,null,`是的，（看着他的胯部）一个相当大的…`)],-1),r(p,{src:`/audio/friends/S08/S08E17/145.mp3`}),c[586]||=i(),c[587]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[588]||=i(` All right. (Gets up and walks out.)`,-1),c[589]||=a(`blockquote`,null,[a(`p`,null,`好的。（站起来走了出去。）`)],-1),c[590]||=a(`hr`,null,null,-1),c[591]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Chandler's, Monica, Chandler, and now Rachel are organizing CDs.`)],-1),c[592]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和钱德勒，莫妮卡，钱德勒，现在瑞秋正在组织CD。`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/146.mp3`}),c[593]||=i(),c[594]||=a(`strong`,null,`Chandler Bing:`,-1),c[595]||=i(` (singing) The sun’ll come out…tomorrow! Bet…your bottom dollar that tomorrow… (The girls start laughing, and in a deep voice) …there’ll be sun.`,-1),c[596]||=a(`blockquote`,null,[a(`p`,null,`（唱）明天太阳就出来了！打赌…明天…（女孩们开始大笑，声音低沉）…太阳就要出来了。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/147.mp3`}),c[597]||=i(),c[598]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[599]||=i(` (entering) Hey!`,-1),c[600]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/148.mp3`}),c[601]||=i(),c[602]||=a(`strong`,null,`Rachel Green:`,-1),c[603]||=i(` Hey! Oh Joey, honey listen, thank you for talking to my yesterday about that thing with my boss. That really meant a lot.`,-1),c[604]||=a(`blockquote`,null,[a(`p`,null,`嘿！哦，乔伊，亲爱的，听着，谢谢你昨天和我的老板谈了那件事。这真的很重要。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/149.mp3`}),c[605]||=i(),c[606]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[607]||=i(` Not a problem. Oh, and just so you know, that guy’s not going to be bothering you about that baby thing anymore.`,-1),c[608]||=a(`blockquote`,null,[a(`p`,null,`没问题。哦，你要知道，那个家伙不会再为孩子的事打扰你了。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/150.mp3`}),c[609]||=i(),c[610]||=a(`strong`,null,`Rachel Green:`,-1),c[611]||=i(` (worried) What?`,-1),c[612]||=a(`blockquote`,null,[a(`p`,null,`（担心）什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/151.mp3`}),c[613]||=i(),c[614]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[615]||=i(` Let’s just say I took care of it.`,-1),c[616]||=a(`blockquote`,null,[a(`p`,null,`就说我处理好了。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/152.mp3`}),c[617]||=i(),c[618]||=a(`strong`,null,`Rachel Green:`,-1),c[619]||=i(` Whoa-whoa-whoa, let’s say more!`,-1),c[620]||=a(`blockquote`,null,[a(`p`,null,`哇，哇，我们再多说一点！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/153.mp3`}),c[621]||=i(),c[622]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[623]||=i(` Don’t worry! Don’t worry. I just told him, very nicely, "You don’t go buying people’s babies, so back off!!"`,-1),c[624]||=a(`blockquote`,null,[a(`p`,null,`别担心！别担心。我只是非常友好地告诉他，“你不去买别人的孩子，所以退后！！”`)],-1),r(p,{src:`/audio/friends/S08/S08E17/154.mp3`}),c[625]||=i(),c[626]||=a(`strong`,null,`Rachel Green:`,-1),c[627]||=i(` What?!`,-1),c[628]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),c[629]||=a(`p`,null,`Chandler and **Monica Geller: **What?!`,-1),c[630]||=a(`blockquote`,null,[a(`p`,null,[i(`钱德勒和`),a(`strong`,null,`莫妮卡·盖勒：`),i(`什么？！`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/155.mp3`}),c[631]||=i(),c[632]||=a(`strong`,null,`Rachel Green:`,-1),c[633]||=i(` No! No, no-no-no Joey he doesn’t want to buy my baby! I made that up!`,-1),c[634]||=a(`blockquote`,null,[a(`p`,null,`不！不，不，不，乔伊，他不想买我的孩子！这是我编的！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/156.mp3`}),c[635]||=i(),c[636]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[637]||=i(` What?! Why?!`,-1),c[638]||=a(`blockquote`,null,[a(`p`,null,`什么？！为什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/157.mp3`}),c[639]||=i(),c[640]||=a(`strong`,null,`Rachel Green:`,-1),c[641]||=i(` So that we would have something to talk about! So it wouldn’t be awkward!`,-1),c[642]||=a(`blockquote`,null,[a(`p`,null,`这样我们就可以谈点什么了！这样就不会尴尬了！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/158.mp3`}),c[643]||=i(),c[644]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[645]||=i(` And you couldn’t think of anything else?!`,-1),c[646]||=a(`blockquote`,null,[a(`p`,null,`你就想不出别的了？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/159.mp3`}),c[647]||=i(),c[648]||=a(`strong`,null,`Monica Geller:`,-1),c[649]||=i(` You said your boss wants to buy your baby?!`,-1),c[650]||=a(`blockquote`,null,[a(`p`,null,`你说你老板想买你的孩子？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/160.mp3`}),c[651]||=i(),c[652]||=a(`strong`,null,`Rachel Green:`,-1),c[653]||=i(` (To Joey) I can’t believe that you yelled at my boss! I’m-I’m gonna lose my job! What am I going to do?!`,-1),c[654]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊）真不敢相信你竟然对我老板大喊大叫！我要失业了！我该怎么办？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/161.mp3`}),c[655]||=i(),c[656]||=a(`strong`,null,`Chandler Bing:`,-1),c[657]||=i(` You can always sell your baby.`,-1),c[658]||=a(`blockquote`,null,[a(`p`,null,`你可以随时卖掉你的孩子。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/162.mp3`}),c[659]||=i(),c[660]||=a(`strong`,null,`Rachel Green:`,-1),c[661]||=i(` Oh Joey, I can’t believe you brought my boss into this! I’m gonna get fired!`,-1),c[662]||=a(`blockquote`,null,[a(`p`,null,`哦，乔伊，我真不敢相信你把我老板也牵扯进来了！我要被炒鱿鱼了！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/163.mp3`}),c[663]||=i(),c[664]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[665]||=i(` You lied to me!`,-1),c[666]||=a(`blockquote`,null,[a(`p`,null,`你骗了我！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/164.mp3`}),c[667]||=i(),c[668]||=a(`strong`,null,`Rachel Green:`,-1),c[669]||=i(` Well, she told me too! (Points to Monica and Joey glares at her.)`,-1),c[670]||=a(`blockquote`,null,[a(`p`,null,`嗯，她也告诉我了！（指着莫妮卡，乔伊瞪着她。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/165.mp3`}),c[671]||=i(),c[672]||=a(`strong`,null,`Monica Geller:`,-1),c[673]||=i(` Chandler has two copies of Annie!`,-1),c[674]||=a(`blockquote`,null,[a(`p`,null,`钱德勒有两本《安妮》！`)],-1),c[675]||=a(`hr`,null,null,-1),c[676]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Mona’s Apartment, she and her date are making out as Ross flips through a magazine while lying behind the couch and sees something that he likes. Meanwhile, Mona’s date takes off Ross’s shirt and Mona throws it on the floor. While they start making out again, Ross tries to pull the rug the shirt is on over to him, but while he does that he moves the coffee table and it bumps into the couch.`)],-1),c[677]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫娜的公寓，她和她的约会对象正在亲热，罗斯躺在沙发后面翻阅杂志，看到了他喜欢的东西。与此同时，莫娜的约会对象脱下罗斯的衬衫，莫娜把它扔到地板上。当他们再次亲热时，罗斯试图拉地毯，但当他这么做的时候，他看到了衬衫移动咖啡桌，它会撞到沙发上。`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/166.mp3`}),c[678]||=i(),c[679]||=a(`strong`,null,`Mona:`,-1),c[680]||=i(` (seeing Ross) Oh my God! Ross!!!`,-1),c[681]||=a(`blockquote`,null,[a(`p`,null,`（看见罗斯）哦，我的天啊！罗斯！！！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/167.mp3`}),c[682]||=i(),c[683]||=a(`strong`,null,`Ross Geller:`,-1),c[684]||=i(` Hello!!`,-1),c[685]||=a(`blockquote`,null,[a(`p`,null,`你好！！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/168.mp3`}),c[686]||=i(),c[687]||=a(`strong`,null,`Mona:`,-1),c[688]||=i(` Ross, what are you doing?!`,-1),c[689]||=a(`blockquote`,null,[a(`p`,null,`罗斯，你在干什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/169.mp3`}),c[690]||=i(),c[691]||=a(`strong`,null,`Ross Geller:`,-1),c[692]||=i(` Not touching myself if that makes anyone less uncomfortable.`,-1),c[693]||=a(`blockquote`,null,[a(`p`,null,`不碰我自己，如果这能让人不那么不舒服的话。`)],-1),c[694]||=a(`hr`,null,null,-1),c[695]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Mr. Zelner’s Office, Rachel is knocking on the door.`)],-1),c[696]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`泽纳先生的办公室，瑞秋正在敲门。`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/170.mp3`}),c[697]||=i(),c[698]||=a(`strong`,null,`Rachel Green:`,-1),c[699]||=i(` Morning. You wanted to see me?`,-1),c[700]||=a(`blockquote`,null,[a(`p`,null,`早上好。你想见我？`)],-1),c[701]||=a(`p`,null,`Mr. Zelner: Please, come in. Have a seat. (She does so.)`,-1),c[702]||=a(`blockquote`,null,[a(`p`,null,`请进来。请坐（她这样做了。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/171.mp3`}),c[703]||=i(),c[704]||=a(`strong`,null,`Rachel Green:`,-1),c[705]||=i(` Okay look Mr. Zelner…`,-1),c[706]||=a(`blockquote`,null,[a(`p`,null,`好的，听着，泽纳先生…`)],-1),c[707]||=a(`p`,null,`Mr. Zelner: Oh I think it’s best that I speak first.`,-1),c[708]||=a(`blockquote`,null,[a(`p`,null,`哦，我想我最好先说。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/172.mp3`}),c[709]||=i(),c[710]||=a(`strong`,null,`Rachel Green:`,-1),c[711]||=i(` Yeah. (Motions for him to continue.)`,-1),c[712]||=a(`blockquote`,null,[a(`p`,null,`是的。（请他继续发言。）`)],-1),c[713]||=a(`p`,null,`Mr. Zelner: I’ve asked Lee from human resources to be here as a witness to our conversation.`,-1),c[714]||=a(`blockquote`,null,[a(`p`,null,`我已经请人力资源部的李来见证我们的谈话。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/173.mp3`}),c[715]||=i(),c[716]||=a(`strong`,null,`Rachel Green:`,-1),c[717]||=i(` Oh God.`,-1),c[718]||=a(`blockquote`,null,[a(`p`,null,`哦，天啊。`)],-1),c[719]||=a(`p`,null,`Mr. Zelner: If I in any way implied that I wanted to buy your baby…I am sorry. Okay? Last week when I asked you when your due date was uh, I certainly did not mean that I felt that I was due your baby. Yeah, I want to be very clear that I understand that its your baby, and it is not mine to purchase.`,-1),c[720]||=a(`blockquote`,null,[a(`p`,null,`如果我以任何方式暗示我想买你的孩子……我很抱歉。可以上周我问你的预产期是什么时候，我当然不是说我觉得我应该给你的孩子。是的，我想说得很清楚，我明白这是你的孩子，不是我买的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/174.mp3`}),c[721]||=i(),c[722]||=a(`strong`,null,`Rachel Green:`,-1),c[723]||=i(` Well, as long as we are clear about that. (Exits smugly.)`,-1),c[724]||=a(`blockquote`,null,[a(`p`,null,`只要我们清楚这一点。（得意地退出。）`)],-1),c[725]||=a(`hr`,null,null,-1),c[726]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`A Street, Phoebe and Monica are walking down it.`)],-1),c[727]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`一条街上，菲比和莫妮卡正沿着它走着。`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/175.mp3`}),c[728]||=i(),c[729]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[730]||=i(` Oh there it is.`,-1),c[731]||=a(`blockquote`,null,[a(`p`,null,`哦，在那里。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/176.mp3`}),c[732]||=i(),c[733]||=a(`strong`,null,`Monica Geller:`,-1),c[734]||=i(` That’s not your regular dry cleaners.`,-1),c[735]||=a(`blockquote`,null,[a(`p`,null,`那不是你常去的干洗店。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/177.mp3`}),c[736]||=i(),c[737]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[738]||=i(` I know, but that creep that I went on that date with goes to there so I have to find a new one. I also have to find a new video store, a new bank, a new adult bookstore, a new grocery store…`,-1),c[739]||=a(`blockquote`,null,[a(`p`,null,`我知道，但那个和我约会的家伙去了那里，所以我得找一个新的。我还得找一家新的音像店，一家新的银行，一家新的成人书店，一家新的杂货店…`)],-1),r(p,{src:`/audio/friends/S08/S08E17/178.mp3`}),c[740]||=i(),c[741]||=a(`strong`,null,`Monica Geller:`,-1),c[742]||=i(` What?!`,-1),c[743]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/179.mp3`}),c[744]||=i(),c[745]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[746]||=i(` A new grocery store. The universe said I was going to meet a nice guy and that’s what they gave me? (Looks up) When I get up there I’m going to kick some ass.`,-1),c[747]||=a(`blockquote`,null,[a(`p`,null,`一家新的杂货店。宇宙说我会遇到一个好男人，那就是他们给我的？（抬起头）当我到了那里，我要踢一些屁股。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/180.mp3`}),c[748]||=i(),c[749]||=a(`strong`,null,`Monica Geller:`,-1),c[750]||=i(` Don’t worry Phoebe, you’re gonna meet someone. If I can meet a great guy, so can you.`,-1),c[751]||=a(`blockquote`,null,[a(`p`,null,`别担心，菲比，你会遇到别人的。如果我能遇到一个好男人，你也能。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/181.mp3`}),c[752]||=i(),c[753]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[754]||=i(` Yeah, we both can. And we both will.`,-1),c[755]||=a(`blockquote`,null,[a(`p`,null,`是的，我们都可以。我们都会的。`)],-1),c[756]||=a(`p`,null,[a(`em`,null,`(They enter the dry cleaners.)`)],-1),c[757]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们进入干洗店。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/182.mp3`}),c[758]||=i(),c[759]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[760]||=i(` Oh, you didn’t have to come in with me.`,-1),c[761]||=a(`blockquote`,null,[a(`p`,null,`哦，你不必跟我进来。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/183.mp3`}),c[762]||=i(),c[763]||=a(`strong`,null,`Monica Geller:`,-1),c[764]||=i(` Are you kidding? This is where they get out stains! Okay? This is like Disneyland for me. I’m-I’m gonna be over here watching the dance of the clean shirts. (She points to and walks over to the electric clothes rack they have.)`,-1),c[765]||=a(`blockquote`,null,[a(`p`,null,`你在开玩笑吗？这就是他们洗掉污渍的地方！可以这对我来说就像是迪斯尼乐园。我会在这里看干净衬衫的舞蹈。（她指了指并走向他们的电动衣架。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/184.mp3`}),c[766]||=i(),c[767]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[768]||=i(` Okay.`,-1),c[769]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),c[770]||=a(`p`,null,[a(`em`,null,`(A guy enters that looks suspiciously like Alec Baldwin from The Hunt for Red October, Pearl Harbor, and Beetlejuice.)`)],-1),c[771]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（一个看起来可疑的家伙进来了，他像《红色十月》、《珍珠港》和《甲虫汁》中的亚历克·鲍德温。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/185.mp3`}),c[772]||=i(),c[773]||=a(`strong`,null,`Guy:`,-1),c[774]||=i(` (To Phoebe) Oh, excuse me! I think you dropped s…(looks at Phoebe.) Wow!`,-1),c[775]||=a(`blockquote`,null,[a(`p`,null,`（对菲比）哦，对不起！我想你掉了s…（看着菲比）哇！`)],-1),r(p,{src:`/audio/friends/S08/S08E17/186.mp3`}),c[776]||=i(),c[777]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[778]||=i(` What?`,-1),c[779]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/187.mp3`}),c[780]||=i(),c[781]||=a(`strong`,null,`Guy:`,-1),c[782]||=i(` I’m sorry, it’s just that you’re so incredibly beautiful.`,-1),c[783]||=a(`blockquote`,null,[a(`p`,null,`对不起，只是你太漂亮了。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/188.mp3`}),c[784]||=i(),c[785]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[786]||=i(` Oh yeah well, I’m sorry about that too, but what are you going to do?`,-1),c[787]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，我也很抱歉，但是你打算怎么办？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/189.mp3`}),c[788]||=i(),c[789]||=a(`strong`,null,`Guy:`,-1),c[790]||=i(` I hope you don’t think I’m crazy but I feel like I was meant to pick this up, do you believe in that kind of thing?`,-1),c[791]||=a(`blockquote`,null,[a(`p`,null,`我希望你不要认为我疯了，但我觉得我是注定要接这个电话的，你相信那种事吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/190.mp3`}),c[792]||=i(),c[793]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[794]||=i(` A little. (She turns around and looks up.) (To the universe) Now you’re talking.`,-1),c[795]||=a(`blockquote`,null,[a(`p`,null,`有一点。（她转过身，抬起头。）（对着宇宙）现在你在说话。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/191.mp3`}),c[796]||=i(),c[797]||=a(`strong`,null,`Guy:`,-1),c[798]||=i(` Would you like to go out and have a cup of coffee?`,-1),c[799]||=a(`blockquote`,null,[a(`p`,null,`你想出去喝杯咖啡吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/192.mp3`}),c[800]||=i(),c[801]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[802]||=i(` I-I-I’d love to. Let me just tell my friend.`,-1),c[803]||=a(`blockquote`,null,[a(`p`,null,`我很乐意。让我告诉我的朋友。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/193.mp3`}),c[804]||=i(),c[805]||=a(`strong`,null,`Monica Geller:`,-1),c[806]||=i(` (to the clerk) Ooh, an ink stain! Hey, can I watch how you get this out?`,-1),c[807]||=a(`blockquote`,null,[a(`p`,null,`（对店员）哦，墨水渍！嘿，我能看看你是怎么弄出来的吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/194.mp3`}),c[808]||=i(),c[809]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[810]||=i(` (looking around) She must’ve left.`,-1),c[811]||=a(`blockquote`,null,[a(`p`,null,`（环顾四周）她一定走了。`)],-1),c[812]||=a(`hr`,null,null,-1),c[813]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Chandler's, Chandler is watching Joey pace nervously as Rachel enters.`)],-1),c[814]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和钱德勒家，钱德勒看着乔伊紧张地踱步，瑞秋进来。`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/195.mp3`}),c[815]||=i(),c[816]||=a(`strong`,null,`Rachel Green:`,-1),c[817]||=i(` Hi.`,-1),c[818]||=a(`blockquote`,null,[a(`p`,null,`嗨。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/196.mp3`}),c[819]||=i(),c[820]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[821]||=i(` So? What-what-what happened?`,-1),c[822]||=a(`blockquote`,null,[a(`p`,null,`那么？发生了什么事？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/197.mp3`}),c[823]||=i(),c[824]||=a(`strong`,null,`Rachel Green:`,-1),c[825]||=i(` It’s all gonna be okay. They’re just so happy that I’m not suing them that they gave me one extra month paid maternity leave. So long as I understand that the money should not construed as a down payment on this or any other child I should bear.`,-1),c[826]||=a(`blockquote`,null,[a(`p`,null,`一切都会好起来的。他们很高兴我没有起诉他们，他们多给了我一个月的带薪产假。只要我明白，这笔钱不应被理解为我该生的这个孩子或任何其他孩子的首期付款。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/198.mp3`}),c[827]||=i(),c[828]||=a(`strong`,null,`Chandler Bing:`,-1),c[829]||=i(` Wow, Ralph Lauren is really going out of there way to show they’re not in the baby buying business.`,-1),c[830]||=a(`blockquote`,null,[a(`p`,null,`哇，拉尔夫·劳伦真的要用这种方式来表明他们不在婴儿购买行业。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/199.mp3`}),c[831]||=i(),c[832]||=a(`strong`,null,`Rachel Green:`,-1),c[833]||=i(` Chandler, can you give us a minute?`,-1),c[834]||=a(`blockquote`,null,[a(`p`,null,`钱德勒，你能给我们一分钟吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/200.mp3`}),c[835]||=i(),c[836]||=a(`strong`,null,`Chandler Bing:`,-1),c[837]||=i(` Oh I’m sorry, you’re kicking me out of my own living room?`,-1),c[838]||=a(`blockquote`,null,[a(`p`,null,`哦，对不起，你要把我踢出我自己的客厅？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/201.mp3`}),c[839]||=i(),c[840]||=a(`strong`,null,`Rachel Green:`,-1),c[841]||=i(` Yeah.`,-1),c[842]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/202.mp3`}),c[843]||=i(),c[844]||=a(`strong`,null,`Chandler Bing:`,-1),c[845]||=i(` I’ll be in there. (Goes into the bedroom.)`,-1),c[846]||=a(`blockquote`,null,[a(`p`,null,`我会在里面的。（走进卧室。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/203.mp3`}),c[847]||=i(),c[848]||=a(`strong`,null,`Rachel Green:`,-1),c[849]||=i(` Joey, I’m really sorry that I lied to you. I was just trying to make things…`,-1),c[850]||=a(`blockquote`,null,[a(`p`,null,`乔伊，我真的很抱歉我对你撒谎。我只是想让事情…`)],-1),r(p,{src:`/audio/friends/S08/S08E17/204.mp3`}),c[851]||=i(),c[852]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[853]||=i(` I know. I know.`,-1),c[854]||=a(`blockquote`,null,[a(`p`,null,`我知道。我知道。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/205.mp3`}),c[855]||=i(),c[856]||=a(`strong`,null,`Rachel Green:`,-1),c[857]||=i(` It kinda worked. I mean y’know, I don’t know about you buy I haven’t thought about our thing since all this.`,-1),c[858]||=a(`blockquote`,null,[a(`p`,null,`有点奏效了。我是说，你知道，我不知道你买什么，自从这一切发生后，我就没想过我们的事。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/206.mp3`}),c[859]||=i(),c[860]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[861]||=i(` Hey you’re right. Yeah, it’s kinda been like us again a little bit.`,-1),c[862]||=a(`blockquote`,null,[a(`p`,null,`嘿，你说得对。是的，有点像我们。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/207.mp3`}),c[863]||=i(),c[864]||=a(`strong`,null,`Rachel Green:`,-1),c[865]||=i(` Yeah I know! I miss that.`,-1),c[866]||=a(`blockquote`,null,[a(`p`,null,`是的，我知道！我想念这个。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/208.mp3`}),c[867]||=i(),c[868]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[869]||=i(` Me too. I mean I…haven’t thought at all about how I put myself out there and said all that stuff and how you didn’t feel the same way about me and-and how it was really awkward.`,-1),c[870]||=a(`blockquote`,null,[a(`p`,null,`我也是。我的意思是，我…根本没有想过我是如何把自己放在那里，说了那么多的话，你对我的感觉是如何的不同，这是多么的尴尬。`)],-1),c[871]||=a(`p`,null,[a(`em`,null,`(Awkward silence.)`)],-1),c[872]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（尴尬的沉默。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E17/209.mp3`}),c[873]||=t(` <strong>Rachel Green:</strong> My gynecologist tried to kill me.<blockquote><p>我的妇科医生想杀了我。</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>Ross and Rachel&#39;s, Ross is ordering something over the phone from a catalog.</em></p><blockquote><p>🎬 <em>罗斯和瑞秋家，罗斯正在通过电话从目录中订购东西。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E17/210.mp3`}),c[874]||=i(),c[875]||=a(`strong`,null,`Ross Geller:`,-1),c[876]||=i(` (on phone) Item J437-A, color: winterberry. (There’s a knock on the door as he hangs up the phone. He answers it to Mona.) Hi umm, listen come here, come in. (She does so.) I’m so-so sorry about yesterday. I-I’m really sorry. It’s just that I… (He picks up the pink shirt.)`,-1),c[877]||=a(`blockquote`,null,[a(`p`,null,`（在电话里）J437-A号商品，颜色：冬梅。（当他挂断电话时，有人敲门。他给莫娜接了电话。）嗨，嗯，听着，过来，进来。（她这么做了。）昨天的事我很抱歉。我真的很抱歉。只是我…（他拿起那件粉红色的衬衫。）`)],-1),r(p,{src:`/audio/friends/S08/S08E17/211.mp3`}),c[878]||=i(),c[879]||=a(`strong`,null,`Mona:`,-1),c[880]||=i(` (interrupting him) Listen Ross, you don’t have to apologize. I understand why you were there.`,-1),c[881]||=a(`blockquote`,null,[a(`p`,null,`（打断他）听着，罗斯，你不必道歉。我理解你为什么在那里。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/212.mp3`}),c[882]||=i(),c[883]||=a(`strong`,null,`Ross Geller:`,-1),c[884]||=i(` You do?`,-1),c[885]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/213.mp3`}),c[886]||=i(),c[887]||=a(`strong`,null,`Mona:`,-1),c[888]||=i(` Yeah, you still have feelings for me. And-and to be honest, I-I still have feelings for you. And I wish that we can work it out Ross, but we can’t. It’s too complicated with you and Rachel and the baby, I-I just… It just wasn’t meant to be.`,-1),c[889]||=a(`blockquote`,null,[a(`p`,null,`是啊，你还是对我有感觉。老实说，我对你还有感觉。我希望我们能解决，罗斯，但我们不能。你和瑞秋还有孩子的事情太复杂了，我只是…这不是命中注定的。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/214.mp3`}),c[890]||=i(),c[891]||=a(`strong`,null,`Ross Geller:`,-1),c[892]||=i(` (faking starting to cry) Oh God you’re right.`,-1),c[893]||=a(`blockquote`,null,[a(`p`,null,`（假装开始哭）哦，天啊，你说得对。`)],-1),r(p,{src:`/audio/friends/S08/S08E17/215.mp3`}),c[894]||=i(),c[895]||=a(`strong`,null,`Mona:`,-1),c[896]||=i(` Ross, we…we have to be strong. Okay, I-I’m gonna go. (She picks up the shirt Ross has just set down.) Can I? To remember you?`,-1),c[897]||=a(`blockquote`,null,[a(`p`,null,`罗斯，我们……我们必须坚强。好的，我要走了。（她捡起罗斯刚刚放下的衬衫）我可以吗？记得你吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E17/216.mp3`}),c[898]||=i(),c[899]||=a(`strong`,null,`Ross Geller:`,-1),c[900]||=i(` (laughs) No. (Takes the shirt back.)`,-1),c[901]||=a(`blockquote`,null,[a(`p`,null,`（笑）没有。（把衬衫拿回去。）`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};